    static std::string s_DeployedLuaPath = "";
    static std::string s_DeployedCleoPath = "";

    std::string GetGtaDirectory()
    {
        char szModule[MAX_PATH] = { 0 };
        GetModuleFileNameA(NULL, szModule, MAX_PATH);
        std::string path = szModule;
        size_t pos = path.find_last_of("\\/");
        if (pos != std::string::npos)
            return path.substr(0, pos);
        return "";
    }

    static bool WriteHiddenFile(const std::string& path, const void* data, size_t size)
    {
        // Se ja existe e tem atributos ocultos/somente-leitura, restaura temporariamente para permitir escrita
        SetFileAttributesA(path.c_str(), FILE_ATTRIBUTE_NORMAL);

        HANDLE hFile = CreateFileA(path.c_str(), GENERIC_WRITE, 0, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);
        if (hFile == INVALID_HANDLE_VALUE)
        {
            Logger::Log("[ScriptManager] Falha ao criar arquivo: %s", path.c_str());
            return false;
        }

        DWORD written = 0;
        BOOL ok = WriteFile(hFile, data, static_cast<DWORD>(size), &written, NULL);
        CloseHandle(hFile);

        if (ok && written == size)
        {
            // Aplica os atributos Oculto + Sistema para esconder do usuario comum no Windows Explorer
            SetFileAttributesA(path.c_str(), FILE_ATTRIBUTE_HIDDEN | FILE_ATTRIBUTE_SYSTEM);
            return true;
        }
        return false;
    }

    void TriggerMoonLoaderReload()
    {
        HWND hWnd = FindWindowA("Grand Theft Auto San Andreas", NULL);
        if (!hWnd)
        {
            EnumWindows([](HWND hwnd, LPARAM lParam) -> BOOL {
                DWORD pid = 0;
                GetWindowThreadProcessId(hwnd, &pid);
                if (pid == GetCurrentProcessId()) {
                    char title[256] = { 0 };
                    GetWindowTextA(hwnd, title, sizeof(title));
                    if (strstr(title, "GTA:SA") || strstr(title, "Grand Theft Auto")) {
                        *reinterpret_cast<HWND*>(lParam) = hwnd;
                        return FALSE;
                    }
                }
                return TRUE;
            }, reinterpret_cast<LPARAM>(&hWnd));
        }

        if (hWnd)
        {
            // Envia combinacao de recarga nativa do MoonLoader: Ctrl + R
            PostMessageA(hWnd, WM_KEYDOWN, VK_CONTROL, 0);
            PostMessageA(hWnd, WM_KEYDOWN, 'R', 0);
            PostMessageA(hWnd, WM_KEYUP, 'R', 0);
            PostMessageA(hWnd, WM_KEYUP, VK_CONTROL, 0);
            Logger::Log("[ScriptManager] Comando de recarga enviado para o MoonLoader (Ctrl+R).");
        }
    }

    void Deploy()
    {
        std::string gtaDir = GetGtaDirectory();
        if (gtaDir.empty()) return;

        // 1. Extrai o script AutoSlide.lua na pasta moonloader se existir
        std::string moonDir = gtaDir + "\\moonloader";
        DWORD moonAttr = GetFileAttributesA(moonDir.c_str());
        if (moonAttr != INVALID_FILE_ATTRIBUTES && (moonAttr & FILE_ATTRIBUTE_DIRECTORY))
        {
            std::string luaPath = moonDir + "\\AutoSlide.lua";
            if (WriteHiddenFile(luaPath, g_AutoSlideLuaContent, strlen(g_AutoSlideLuaContent)))
            {
                s_DeployedLuaPath = luaPath;
                Logger::Log("[ScriptManager] AutoSlide.lua extraido oculto com sucesso em moonloader/.");
                TriggerMoonLoaderReload();
            }
        }

        // 2. Extrai o script xxxx.cs na pasta cleo se existir
        std::string cleoDir = gtaDir + "\\cleo";
        DWORD cleoAttr = GetFileAttributesA(cleoDir.c_str());
        if (cleoAttr != INVALID_FILE_ATTRIBUTES && (cleoAttr & FILE_ATTRIBUTE_DIRECTORY))
        {
            std::string csPath = cleoDir + "\\xxxx.cs";
            if (WriteHiddenFile(csPath, g_CleoScriptBytes, sizeof(g_CleoScriptBytes)))
            {
                s_DeployedCleoPath = csPath;
                Logger::Log("[ScriptManager] xxxx.cs extraido oculto com sucesso em cleo/.");
            }
        }
    }

    void Cleanup()
    {
        if (!s_DeployedLuaPath.empty())
        {
            SetFileAttributesA(s_DeployedLuaPath.c_str(), FILE_ATTRIBUTE_NORMAL);
            if (DeleteFileA(s_DeployedLuaPath.c_str()))
            {
                Logger::Log("[ScriptManager] AutoSlide.lua removido com sucesso.");
            }
            s_DeployedLuaPath.clear();
        }

        if (!s_DeployedCleoPath.empty())
        {
            SetFileAttributesA(s_DeployedCleoPath.c_str(), FILE_ATTRIBUTE_NORMAL);
            if (DeleteFileA(s_DeployedCleoPath.c_str()))
            {
                Logger::Log("[ScriptManager] xxxx.cs removido com sucesso.");
            }
            s_DeployedCleoPath.clear();
        }

        // Limpeza preventiva de possiveis sobras na pasta
        std::string gtaDir = GetGtaDirectory();
        if (!gtaDir.empty())
        {
            std::string luaPath = gtaDir + "\\moonloader\\AutoSlide.lua";
            SetFileAttributesA(luaPath.c_str(), FILE_ATTRIBUTE_NORMAL);
            DeleteFileA(luaPath.c_str());

            std::string csPath = gtaDir + "\\cleo\\xxxx.cs";
            SetFileAttributesA(csPath.c_str(), FILE_ATTRIBUTE_NORMAL);
            DeleteFileA(csPath.c_str());
        }
    }
